"use client";

import { Save } from "lucide-react";

export default function SiteContentPage() {
    return (
        <div className="space-y-6">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-2xl font-bold tracking-tight text-gray-900">Site Content</h1>
                    <p className="text-sm text-gray-500">Manage static text and sections.</p>
                </div>
                <button className="inline-flex items-center justify-center gap-2 rounded-lg bg-black px-4 py-2 text-sm font-medium text-white transition-colors hover:bg-gray-800">
                    <Save className="h-4 w-4" />
                    Save Changes
                </button>
            </div>

            <div className="grid gap-6 lg:grid-cols-2">
                {/* Hero Section */}
                <div className="rounded-xl border bg-white p-6 shadow-sm">
                    <h3 className="mb-4 text-lg font-semibold text-gray-900">Hero Section</h3>
                    <div className="space-y-4">
                        <div>
                            <label className="mb-2 block text-sm font-medium text-gray-700">Main Title</label>
                            <input
                                type="text"
                                defaultValue="OUR WORK"
                                className="w-full rounded-lg border border-gray-300 p-2 text-sm outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
                            />
                        </div>
                        <div>
                            <label className="mb-2 block text-sm font-medium text-gray-700">Subtitle</label>
                            <textarea
                                rows={3}
                                defaultValue="A COLLECTION OF DIGITAL EXPERIENCES CRAFTED WITH PRECISION."
                                className="w-full rounded-lg border border-gray-300 p-2 text-sm outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
                            />
                        </div>
                    </div>
                </div>

                {/* Footer Section */}
                <div className="rounded-xl border bg-white p-6 shadow-sm">
                    <h3 className="mb-4 text-lg font-semibold text-gray-900">Contact / Footer</h3>
                    <div className="space-y-4">
                        <div>
                            <label className="mb-2 block text-sm font-medium text-gray-700">Email Address</label>
                            <input
                                type="email"
                                defaultValue="aryantiwari0724@gmail.com"
                                className="w-full rounded-lg border border-gray-300 p-2 text-sm outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
                            />
                        </div>
                        <div>
                            <label className="mb-2 block text-sm font-medium text-gray-700">Phone Number</label>
                            <input
                                type="text"
                                defaultValue="+91 9470650991"
                                className="w-full rounded-lg border border-gray-300 p-2 text-sm outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
                            />
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}
